code:
// ── 🧭 sel-cara-auto · la extrusión se orienta SOLA hacia donde hay aire ──────────────────────────
//
// Dueño (2026-08-29): «*si por ejemplo selecciono un bloque del suelo, lo normal es que la estrusion se
// priorice hacia arriba, ya que hacia abajo ya hay bloques, por lo tanto, se ha de detectar si hay aire
// para estruir solamente en uno de los lados y priorizar esa direccion sin necesidad de hacer clic con
// el boton central. Si se pulsa el boton central se cambiaría, pero se priorizaria inicialmente la
// direccion que esta vacia*». Y de Shift: «*si se selecciona el bloque que esta en el perfil de un
// acantilado y solamente hay aire en frente de él, se priorizaria el crecimiento de bloques hacia
// adelante, por el contrario si se selecciona un bloque lejano de una cornisa que solamente tiene aire
// hacia el jugador, se priorizaria crear bloques hacia el jugador*». Y el tope: «*Si hay aire en mas una
// direccion arriba/abajo para control presionado, o adelante/hacia atras con shift presionado, no seria
// necesario priorizar nada*».
//
// QUÉ HACE, EXACTAMENTE: no inventa ninguna extrusión nueva. El motor YA sabe construir por las dos
// caras — es REQ-EXTRU4: `mc.selOpuesta` dice cuál, y el clic central la conmuta. Esto sólo PONE ESE
// INTERRUPTOR SOLO, mirando dónde hay aire, ANTES de que la rueda haga nada. Ni una extrusión más ni
// una menos: las mismas cuatro de siempre, elegidas sin tener que pensarlas.
//
//   Ctrl  · aire ARRIBA y no abajo    → cara de ARRIBA (selOpuesta=false) · ↑ construye encima
//           aire ABAJO  y no arriba   → cara de ABAJO  (selOpuesta=true)  · ↓ construye debajo
//   Shift · aire DELANTE y no hacia ti → cara del FONDO (selOpuesta=true)  · ↑ tiende puente adelante
//           aire HACIA TI y no delante → cara de ENFRENTE (false)          · ↓ construye hacia ti
//   en los dos casos: aire en LAS DOS o en NINGUNA ⇒ no se toca nada, tal cual lo pidió el dueño.
//
// «AIRE» ES CELDA VACÍA (`mc.grid === 0`), y el borde del mundo NO cuenta como aire: allí no se puede
// construir, así que priorizar hacia allí sería mandar la rueda contra una pared. El agua y la lava
// TAMPOCO son aire aquí: son bloques, y extruir contra ellos es una decisión distinta que el dueño no
// ha pedido.
//
// LAS CARAS SE MIDEN COMO LAS MIDE EL MOTOR, no por las esquinas de la caja: por COLUMNAS (Ctrl) y por
// FILAS (Shift), quedándose con la cima/el suelo y con la cara que da al jugador/al fondo. Es la misma
// cuenta de `mcSelExtruir` y `mcSelExtruirFrente`, y tiene que serlo: si la silueta que se mide no es la
// que luego se extruye, el automático prioriza una dirección y la rueda hace otra.
//
// EL CLIC CENTRAL SIGUE MANDANDO. En cuanto se pulsa, esta selección queda MARCADA A MANO y el
// automático no vuelve a tocarla — si no, la muesca siguiente le daría la vuelta a lo que el dueño
// acaba de elegir y el clic central no serviría para nada. La marca SIGUE a la caja mientras se extruye
// (la caja se mueve en cada muesca) y se suelta sola al marcar una selección nueva.
//
// TAMBIÉN ORIENTA LA GUÍA (REQ-EXTRU5): el ✚ verde y el ▬ rojo tienen que enseñar la cara que se va a
// usar ANTES de tocar la rueda, o el automático sería invisible hasta que ya es tarde. Por eso hay un
// tercer enganche en `mcSelGuiaFirma`, que es lo único que corre con la tecla pulsada y sin muesca.
//
// Y VALE CON UN SOLO CLIC: la pieza puede ser la caja CONFIRMADA o la FANTASMA del primer clic, porque
// la rueda extruye las dos (auto-confirma la fantasma). Ver `fantasma()` más abajo — v1 sólo miraba las
// confirmadas y por eso, sin segundo clic, se quedaba con la cara de la vez anterior.
//
// API: game.selAuto.on() / .off() / .estado() / .puesto() / .decide('ctrl'|'shift') / .suelta()

const W = window;
const VERSION = 'sel-auto-v2';   // v2 · también decide sobre la caja FANTASMA (un solo clic)

// `mc` es un `const` de nivel superior de app.js: NO está en `window`, sólo se alcanza por identificador
// pelado. Por eso se mira `typeof mc` y no `W.mc` (que siempre sería undefined).
if (typeof mc === 'undefined' || !mc) {
  console.warn('🧭 sel-cara-auto: no hay motor de mundo. Abre /map/<nombre>.');
  return 'sin motor';
}

// ⛔ CARGARLO DOS VECES NO ES INOCENTE. Cada carga es un cierre NUEVO con su propio `manual`/`cache`, y
// la última línea publica SU `game.selAuto`. Si los envoltorios ya los puso la carga anterior, `on()`
// devuelve 'ya' y no envuelve nada: quedarían los envoltorios de la 1ª carga (que escriben en el
// `manual` de la 1ª) hablando con la API de la 2ª (que lee el suyo, siempre vacío) ⇒ el clic central
// dejaría de marcar la selección. Se sale antes de tocar nada y manda el que ya estaba.
if (W.game && W.game.selAuto && typeof W.game.selAuto.puesto === 'function' && W.game.selAuto.puesto()) {
  return 'sel-cara-auto · ya estaba puesto (no se reinstala; game.selAuto.off() para quitarlo)';
}

const NECESITA = ['mcSelExtruir', 'mcSelExtruirFrente', 'mcSelConmutaCaraOpuesta', 'mcSelGuiaFirma',
                  'mcEjeMirada', 'mcSelForEach', 'mcSelGuiaFantasma', 'mcSelGuiaCeldasFantasma',
                  'mcInside', 'mcIdx', 'toast'];
const faltan = NECESITA.filter(n => typeof W[n] !== 'function');
if (faltan.length) {
  console.warn('🧭 sel-cara-auto: al motor le faltan → ' + faltan.join(', ') +
               ' — ¿app.js anterior a REQ-EXTRU4/REQ-EXTRU5?');
  return 'motor incompleto: falta ' + faltan.join(', ');
}

// Una selección enorme se recorre entera para medir sus caras. Se hace sólo cuando cambia algo (ver la
// caché de `aplica`), pero con la tecla pulsada y el mundo cambiando puede tocar por frame ⇒ tope, igual
// que `MC_SELGUIA_TOPE_VOX` le pone tope a la guía. Pasado el tope no se prioriza: manda el clic central.
const TOPE_VOX = 60000;

// ── mirar el mundo ────────────────────────────────────────────────────────────────────────────────
function cajas() { return mc.selCajas || []; }

// LA CAJA FANTASMA (dueño, 2026-08-29): «*cuando no se confirma la seleccion con un segundo clic a
// veces no se eligen bien la dirección […] si se confirma con el segundo clic si que se orienta bien,
// pero no deberia de ser necesario*».
// Con UN solo clic hay esquina fijada (`mc.selA`) pero todavía no hay caja (`mc.selBox`), y la rueda ya
// sabe qué hacer con eso: auto-confirma tomando el bloque apuntado como esquina B (REQ-EXTRU5). O sea
// que SÍ hay una pieza concreta sobre la que decidir, y hay que decidir sobre ELLA — que es exactamente
// la que el motor va a extruir. Mirando sólo `mc.selCajas` no se decidía nada y `mc.selOpuesta` se
// quedaba con lo de la vez anterior: de ahí que saliera «arriba» donde tocaba «abajo».
function fantasma() {
  if (mc.selBox || mc.tool !== 'select') return null;
  return mcSelGuiaFantasma();                      // null si no hay ni primer clic, o si es gigante
}

function huella() {
  const f = fantasma();
  // La esquina B de la fantasma va pegada a la mira, así que se mueve sola: tiene que entrar en la
  // huella o la caché daría por buena una decisión de hace tres bloques.
  if (f) return 'F' + f.a.join(',') + '>' + f.b.join(',');
  const c = cajas();
  let s = '';
  for (let i = 0; i < c.length; i++) s += c[i].a.join(',') + '>' + c[i].b.join(',') + ';';
  return s;
}

function volumen() {
  const f = fantasma();
  if (f) return f.vol;
  const c = cajas();
  let v = 0;
  for (let i = 0; i < c.length; i++) {
    const s = c[i];
    v += (Math.abs(s.a[0] - s.b[0]) + 1) * (Math.abs(s.a[1] - s.b[1]) + 1) * (Math.abs(s.a[2] - s.b[2]) + 1);
  }
  return v;
}

// Las celdas CON BLOQUE de lo que haya: caja(s) confirmada(s) o fantasma. Las dos puertas del motor
// tienen la misma semántica (sólo sólidos, y dicen de qué caja sale cada celda), así que el resto del
// snippet no se entera de cuál de las dos está mirando.
function recorre(cb) {
  const f = fantasma();
  if (f) { mcSelGuiaCeldasFantasma(f, function (x, y, z, ci) { cb(x, y, z, ci); }, 0); return true; }
  if (!mc.selBox || !cajas().length) return false;
  mcSelForEach(function (x, y, z, id, ci) { cb(x, y, z, ci); });
  return true;
}

// Fuera del mundo NO es aire: no se puede construir ahí, y priorizar hacia el borde sería prometer una
// muesca que no va a pasar.
function aire(x, y, z) { return mcInside(x, y, z) && mc.grid[mcIdx(x, y, z)] === 0; }

// ── la decisión ───────────────────────────────────────────────────────────────────────────────────
// Devuelve `true` (cara opuesta), `false` (cara normal) o `null` = «no hay nada que priorizar».
function decide(modo) {
  // Vale la caja confirmada Y la fantasma del primer clic: las dos son piezas que la rueda va a extruir.
  if (mc.tool !== 'select') return null;
  if (!fantasma() && (!mc.selBox || !cajas().length)) return null;
  if (volumen() > TOPE_VOX) return null;

  if (modo === 'ctrl') {
    // Cima y suelo de cada columna. La columna es (caja, x, z) y NO (x, z): dos cajas pueden caer sobre
    // el mismo sitio a distinta altura —una en el tejado y otra en el sótano— y son dos columnas
    // (REQ-SEL1). Son las mismas que usan `mcSelExtruir` (la cima) y `mcSelExtruirAbajo` (el suelo).
    const col = new Map();
    recorre(function (x, y, z, ci) {
      const k = ci + ':' + x + ',' + z, v = col.get(k);
      if (!v) col.set(k, { alta: y, baja: y, x: x, z: z });
      else { if (y > v.alta) v.alta = y; if (y < v.baja) v.baja = y; }
    });
    if (!col.size) return null;                    // selección vacía: manda el motor (REQ-EXTRU3)
    let arriba = 0, abajo = 0;
    col.forEach(function (v) {
      if (aire(v.x, v.alta + 1, v.z)) arriba++;
      if (aire(v.x, v.baja - 1, v.z)) abajo++;
    });
    if (arriba && !abajo) return false;            // sólo cabe hacia arriba → cara de ARRIBA
    if (abajo && !arriba) return true;             // sólo cabe hacia abajo → cara de ABAJO
    return null;                                   // las dos o ninguna: no se prioriza nada
  }

  // Shift. El eje sale de la MIRADA y se recalcula cada vez, igual que hace el motor: el jugador se gira
  // y el gesto se gira con él. `sN` apunta AL FRENTE, o sea alejándose del jugador.
  const m = mcEjeMirada(), eje = m.eje, sN = m.sN;
  const fila = new Map();
  recorre(function (x, y, z, ci) {
    const p = eje === 0 ? x : z;
    // La fila son las dos coordenadas que NO son el eje; se guarda la que no varía para el vecino.
    const k = ci + ':' + y + ',' + (eje === 0 ? z : x), v = fila.get(k);
    if (!v) fila.set(k, { max: p, min: p, x: x, y: y, z: z });
    else { if (p > v.max) v.max = p; if (p < v.min) v.min = p; }
  });
  if (!fila.size) return null;
  let delante = 0, haciaTi = 0;
  fila.forEach(function (v) {
    const pFrente = sN > 0 ? v.max : v.min;        // la cara que mira AL FRENTE (lejos del jugador)
    const pCerca  = sN > 0 ? v.min : v.max;        // la que DA LA CARA al jugador
    const fx = eje === 0 ? pFrente + sN : v.x, fz = eje === 2 ? pFrente + sN : v.z;
    const cx = eje === 0 ? pCerca  - sN : v.x, cz = eje === 2 ? pCerca  - sN : v.z;
    if (aire(fx, v.y, fz)) delante++;
    if (aire(cx, v.y, cz)) haciaTi++;
  });
  if (delante && !haciaTi) return true;            // sólo hay hueco al frente → cara del FONDO (puente)
  if (haciaTi && !delante) return false;           // sólo hay hueco hacia ti → cara de ENFRENTE
  return null;
}

// ── aplicarla ─────────────────────────────────────────────────────────────────────────────────────
let manual = null;   // huella de la selección en la que el dueño pulsó el clic central
let cache  = null;   // clave de la última decisión: sin esto se rescanearía la selección cada frame
let ultima = null;   // qué se decidió, para `estado()`

function clave(modo) {
  // La mirada entra sólo con Shift, que es donde cambia el eje; con Ctrl el eje es siempre +Y.
  return modo + '|' + huella() + '|' + (mc.gridGen | 0) +
         (modo === 'shift' ? '|' + mcEjeMirada().nombre : '');
}

function aplica(modo) {
  const h = huella();
  if (!h) { cache = null; ultima = null; return; }
  if (manual !== null && manual === h) { ultima = 'a mano'; return; }   // mandó el clic central
  const k = clave(modo);
  if (k === cache) return;                         // ni la caja, ni el mundo, ni la mirada: no se remira
  cache = k;
  const d = decide(modo);
  ultima = (d === null) ? 'sin prioridad (aire en los dos lados o en ninguno)'
                        : (d ? 'cara opuesta' : 'cara normal');
  if (d !== null) mc.selOpuesta = d;
}

function suelta() { manual = null; cache = null; return 'automático re-armado'; }

// ── las costuras ──────────────────────────────────────────────────────────────────────────────────
// `base` sale de `._orig` si ya había envoltorio nuestro, así que volver a cargar el snippet reemplaza
// el de antes en vez de apilarse encima.
function envuelve(nombre, hazlo) {
  const f = W[nombre];
  if (f._selAuto === VERSION) return 'ya';
  const base = f._selAuto ? f._orig : f;
  const env = function () { return hazlo.call(this, base, arguments); };
  env._selAuto = VERSION;
  env._orig = base;
  W[nombre] = env;                                 // app.js las llama por nombre pelado ⇒ esto las cambia
  return 'puesto';
}

function envuelveExtrusor(nombre, modo) {
  return envuelve(nombre, function (base, args) {
    const dir = args[0];
    // Las mismas condiciones de entrada que el original: sin muesca, sin herramienta o sin caja esto no
    // es asunto nuestro y pasa de largo intacto.
    if (!(dir && mc.tool === 'select' && mc.selBox)) return base.apply(this, args);
    const eraManual = (manual !== null && manual === huella());
    aplica(modo);
    const r = base.apply(this, args);
    // La caja SE MUEVE en cada muesca (el motor la estira o la encoge por su cara). Si estaba marcada a
    // mano, la marca tiene que seguirla: si no, a la muesca siguiente su huella ya no casaría y el
    // automático le daría la vuelta a la elección del dueño justo después de que la hiciera.
    if (eraManual) manual = huella();
    cache = null;                                  // la caja y el mundo han cambiado: volver a mirar
    return r;
  });
}

function envuelveGuia() {
  return envuelve('mcSelGuiaFirma', function (base, args) {
    // Sólo con la tecla pulsada, con caja hecha y SIN pieza en vuelo: pegando, la guía habla del cúmulo
    // que vuela y no de la selección, y ahí no hay cara que elegir.
    const modo = mc.selGuiaModo;
    // ⛔ NO se exige `mc.selBox`: con un solo clic la pieza es la FANTASMA, y era justo ahí donde el
    // automático no llegaba a decidir y la guía enseñaba la cara de la vez anterior.
    if ((modo === 'ctrl' || modo === 'shift') && !mc.pasteActive && mc.tool === 'select')
      aplica(modo);                                // antes de la firma: así el ✚/▬ salen ya orientados
    return base.apply(this, args);
  });
}

function envuelveCentral() {
  return envuelve('mcSelConmutaCaraOpuesta', function (base, args) {
    const r = base.apply(this, args);
    manual = huella();                             // desde aquí manda el dueño en esta selección
    cache = null;
    ultima = 'a mano';
    return r;
  });
}

// ── mando ─────────────────────────────────────────────────────────────────────────────────────────
function on() {
  const a = envuelveExtrusor('mcSelExtruir', 'ctrl');
  const b = envuelveExtrusor('mcSelExtruirFrente', 'shift');
  const c = envuelveGuia();
  const d = envuelveCentral();
  suelta();
  return (a === 'ya' && b === 'ya' && c === 'ya' && d === 'ya')
    ? 'ya estaba puesto'
    : 'la extrusión se orienta sola hacia el aire';
}

function off() {
  let n = 0;
  ['mcSelExtruir', 'mcSelExtruirFrente', 'mcSelGuiaFirma', 'mcSelConmutaCaraOpuesta'].forEach(function (k) {
    const f = W[k];
    if (f && f._selAuto && f._orig) { W[k] = f._orig; n++; }
  });
  manual = null; cache = null; ultima = null;
  // ⛔ NO se toca `mc.selOpuesta`: la cara en la que se haya quedado es la que el dueño está viendo en la
  // guía, y cambiarla al salir movería la selección bajo sus pies. El clic central sigue conmutándola.
  return n ? 'fuera — la cara vuelve a elegirse sólo con el clic central' : 'ya estaba fuera';
}

function puesto() { return typeof mcSelExtruir === 'function' && mcSelExtruir._selAuto === VERSION; }

function describe(d, siNormal, siOpuesta) {
  return d === null ? 'nada que priorizar (aire en los dos lados o en ninguno)'
                    : 'construir ' + (d ? siOpuesta : siNormal);
}

function estado() {
  const m = mcEjeMirada();
  const modo = (mc.selGuiaModo === 'ctrl' || mc.selGuiaModo === 'shift') ? mc.selGuiaModo : null;
  return {
    puesto: puesto(),
    version: VERSION,
    herramienta: mc.tool,
    hayCaja: !!mc.selBox,
    cajas: cajas().length,
    volumen: volumen(),
    tope: TOPE_VOX,
    caraOpuesta: !!mc.selOpuesta,
    aMano: (manual !== null && manual === huella()),
    ultima: ultima,
    teclaAhora: modo || '(ninguna)',
    ejeMirada: m.nombre,
    diriaCtrl: describe(decide('ctrl'), 'encima (cara de arriba)', 'debajo (cara de abajo)'),
    diriaShift: describe(decide('shift'), 'hacia ti (cara de enfrente)', 'adelante (cara del fondo)'),
    nota: 'aMano=true ⇒ mandó el clic central y el automático no toca esta selección; ' +
          'game.selAuto.suelta() lo re-arma sin tener que marcarla otra vez.'
  };
}

game.selAuto = { on: on, off: off, estado: estado, puesto: puesto, decide: decide, suelta: suelta };

const r = on();

toast('🧭 La extrusión se orienta sola hacia el aire · el clic central sigue mandando · game.selAuto.off()', 6);

return 'sel-cara-auto · ' + r;
